export declare function createCuaPipSessionOwner(options: {
  enabled: boolean;
  resolveCredentials: () => Promise<{ socketPath: string } | undefined>;
  createClient?: (options: PipSessionClientOptions) => PipSessionClient;
  logger?: ServiceLogger;
