// PipSessionClientOptions has optional socketPath,timeoutMs,reconnectAttempts,
// reconnectDelayMs,peerChecker; onDiagnostic?:({code:string,message?:string})=>void.
// ServiceLogger has debug/info/warn/error(traceId:string|undefined,...args:unknown[]):void.
